cd /home/minhbien/Documents/lemo-opuscar && cat > proj2.mjs <<'EOF'
import * as THREE from 'three';
const K=2.6, S=1.6*K;
const phonePos=new THREE.Vector3(-.78,.0088*K/2,.70);
function cam(dist,height,side,fov=32){
  const L=phonePos.clone();
  const P=L.clone().add(new THREE.Vector3(side*dist*.70,height,dist));
  const c=new THREE.PerspectiveCamera(fov,1920/1080,.01,100);
  c.position.copy(P); c.lookAt(L); c.updateMatrixWorld(); c.updateProjectionMatrix();
  return c;
}
function proj(c,p,label){
  const v=p.clone().project(c);
  console.log(label,'px',((v.x+1)/2*1920).toFixed(0),((-v.y+1)/2*1080).toFixed(0));
}
const c5=cam(.624,.3,1), c6=cam(.576,.405,-1);
const c161=cam(.576,.605,1);
// thermo parts (thermoA at (-.78,.0144,.87), rot.x=.08, scale S)
const th=new THREE.Vector3(-.78,.0144,.87);
const off=(lz)=>{const v=new THREE.Vector3(0,0,lz*S); v.applyAxisAngle(new THREE.Vector3(1,0,0),.08); return v.add(th);};
for(const [n,lz] of [['sleeve',-.0128],['probe',-.0182],['tip',-.0232],['collar',-.0095]]){
  proj(c5,off(lz),'c5 '+n);
  proj(c6,off(lz),'c6 '+n);
  proj(c161,off(lz),'c161 '+n);
}
// text on screen: world x -.8557..-.761, z .612
proj(c5,new THREE.Vector3(-.81,.0239,.612),'c5 textMid');
proj(c6,new THREE.Vector3(-.81,.0239,.612),'c6 textMid');
proj(c161,new THREE.Vector3(-.81,.0239,.612),'c161 textMid');
// unplugged plug at (-1.089,.0135,.690)
proj(c161,new THREE.Vector3(-1.089,.0135,.690),'c161 loosePlug');
proj(c161,new THREE.Vector3(-.9789,.0114,.70),'c161 portMouth');
EOF
node proj2.mjs; rm -f proj2.mjs
